<?php
require __DIR__.'/../app/bootstrap.php';require_permission('accounts.manage');require_once __DIR__.'/../app/accounting.php';require_once __DIR__.'/../app/payments.php';
$msg=$err=null;$admin=current_user();$adminId=(int)$admin['id'];accounting_sync_invoice_statuses();

function acct_rows(string $sql,array $params=[]): array {try{$q=db()->prepare($sql);$q->execute($params);return $q->fetchAll();}catch(Throwable $e){return [];}}
function acct_scalar(string $sql,array $params=[]): float {try{$q=db()->prepare($sql);$q->execute($params);return (float)($q->fetchColumn()?:0);}catch(Throwable $e){return 0;}}
function csv_out(string $name,array $header,array $rows): never {header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="'.$name.'"');$o=fopen('php://output','w');fputcsv($o,$header);foreach($rows as $r)fputcsv($o,$r);fclose($o);exit;}

if(isset($_GET['export'])&&!setting_bool('accounts_csv_export_enabled',true))throw new RuntimeException('Accounts CSV exports are disabled in Platform Settings.');
if(isset($_GET['export'])&&$_GET['export']==='trial'){
    $rows=accounting_trial_balance();csv_out('trial-balance-'.date('Ymd').'.csv',['Code','Account','Type','Debit','Credit','Balance'],array_map(fn($r)=>[$r['code'],$r['name'],$r['account_type'],$r['total_debit'],$r['total_credit'],$r['balance']],$rows));
}
if(isset($_GET['export'])&&$_GET['export']==='ledger'){
    $aid=(int)($_GET['account']??0);$a=accounting_account($aid);if(!$a)throw new RuntimeException('Account not found.');$lines=accounting_ledger_lines($aid,5000);$running=0;$data=[];foreach($lines as $l){$running+=accounting_normal_balance((string)$a['account_type'],(float)$l['debit'],(float)$l['credit']);$data[]=[$l['journal_date'],$l['reference'],$l['description'],$l['business_name']?:'',number_format((float)$l['debit'],2,'.',''),number_format((float)$l['credit'],2,'.',''),number_format($running,2,'.','')];}csv_out('ledger-'.$a['code'].'-'.date('Ymd').'.csv',['Date','Reference','Description','Business','Debit','Credit','Running Balance'],$data);
}

if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  csrf_check();$action=(string)($_POST['action']??'journal');
  if($action==='journal'){
    if(!setting_bool('accounts_manual_journal_enabled',true))throw new RuntimeException('Manual journal entries are disabled in Platform Settings.');
    $debit=(int)($_POST['debit_account']??0);$credit=(int)($_POST['credit_account']??0);$amount=max(0,(float)($_POST['amount']??0));if(!$debit||!$credit||$debit===$credit||$amount<=0)throw new RuntimeException('Choose different debit/credit accounts and enter an amount.');
    $business=(int)($_POST['business_id']??0)?:null;$description=trim((string)($_POST['description']??''));if($description==='')throw new RuntimeException('Journal description is required.');
    accounting_post_journal($description,[['account_id'=>$debit,'debit'=>$amount,'business_id'=>$business,'memo'=>trim((string)($_POST['memo']??''))],['account_id'=>$credit,'credit'=>$amount,'business_id'=>$business,'memo'=>trim((string)($_POST['memo']??''))]],'manual',null,$adminId,$_POST['journal_date']?:date('Y-m-d'));$msg='Balanced journal entry posted.';
  }
  elseif($action==='create_account'){
    $code=trim((string)($_POST['code']??''));$name=trim((string)($_POST['name']??''));$type=(string)($_POST['account_type']??'asset');if($code===''||$name==='')throw new RuntimeException('Account code and name are required.');if(!in_array($type,['asset','liability','equity','revenue','expense'],true))throw new RuntimeException('Invalid account type.');
    db()->prepare("INSERT INTO accounting_accounts(code,name,account_type,description,status) VALUES(?,?,?,?,1)")->execute([$code,$name,$type,trim((string)($_POST['description']??''))]);$msg='Ledger account created.';
  }
  elseif($action==='invoice_paid'){
    $invoice=subscription_invoice((int)$_POST['invoice_id']);if(!$invoice||!$invoice['payment_order_id'])throw new RuntimeException('Invoice/payment order not found.');
    mark_payment_order_paid((int)$invoice['payment_order_id'],(string)($_POST['gateway']??'cash'),'LEDGER-'.strtoupper(bin2hex(random_bytes(3))),['approved_from_accounts'=>true],$adminId);$msg='Invoice payment posted.';
  }
  elseif($action==='invoice_void'){accounting_void_invoice((int)$_POST['invoice_id'],$adminId);$msg='Invoice voided.';}
 }catch(Throwable $e){$err=$e->getMessage();}
}

$accounts=accounting_accounts(false);$trial=accounting_trial_balance();$businesses=acct_rows("SELECT id,name FROM businesses ORDER BY name");
$invoices=subscription_invoices('',null,300);
$journals=acct_rows("SELECT j.*,u.name created_by_name,(SELECT COALESCE(SUM(debit),0) FROM accounting_journal_lines WHERE journal_id=j.id) amount FROM accounting_journals j LEFT JOIN users u ON u.id=j.created_by ORDER BY j.id DESC LIMIT 250");
$assets=0;$liabilities=0;$equity=0;$revenue=0;$expenses=0;foreach($trial as $r){$v=(float)$r['balance'];if($r['account_type']==='asset')$assets+=$v;elseif($r['account_type']==='liability')$liabilities+=$v;elseif($r['account_type']==='equity')$equity+=$v;elseif($r['account_type']==='revenue')$revenue+=$v;elseif($r['account_type']==='expense')$expenses+=$v;}
$netIncome=$revenue-$expenses;$receivable=accounting_account_by_key('accounts_receivable');$ar=$receivable?accounting_account_balance((int)$receivable['id']):0;
$cashKeys=['cash_on_hand','bank','jazzcash','easypaisa','payfast'];$cash=0;foreach($cashKeys as $k){$a=accounting_account_by_key($k);if($a)$cash+=accounting_account_balance((int)$a['id']);}
$tab=in_array(($_GET['tab']??''),['dashboard','ledger','journal','invoices','business','chart'],true)?$_GET['tab']:'dashboard';
$selectedAccount=(int)($_GET['account']??($accounts[0]['id']??0));$selected=accounting_account($selectedAccount);$ledger=$selected?accounting_ledger_lines($selectedAccount,1500):[];
$businessId=(int)($_GET['business_id']??0);if($businessId&&!setting_bool('accounts_business_ledger_enabled',true))$businessId=0;$statement=$businessId?accounting_business_statement($businessId,1500):[];
$businessInfo=null;if($businessId){$q=db()->prepare("SELECT * FROM businesses WHERE id=?");$q->execute([$businessId]);$businessInfo=$q->fetch();}
require __DIR__.'/../app/layout.php';page_start('Accounts & Ledger',true);
?>
