<div class="acct-dashboard-grid"><section class="card"><div class="acct-panel-head"><div><h3>Trial Balance</h3><span>Debit and credit movements across active ledger accounts.</span></div><a href="?export=trial">Export CSV</a></div><div class="acct-table-wrap"><table><tr><th>Code</th><th>Account</th><th>Type</th><th>Debit</th><th>Credit</th><th>Balance</th></tr><?php foreach($trial as $r):if(abs((float)$r['total_debit'])<.005&&abs((float)$r['total_credit'])<.005)continue;?><tr><td><?=e($r['code'])?></td><td><a href="?tab=ledger&account=<?=e($r['id'])?>"><?=e($r['name'])?></a></td><td><?=e($r['account_type'])?></td><td>Rs <?=e(number_format((float)$r['total_debit'],2))?></td><td>Rs <?=e(number_format((float)$r['total_credit'],2))?></td><td><b>Rs <?=e(number_format((float)$r['balance'],2))?></b></td></tr><?php endforeach;?></table></div></section><section class="card"><div class="acct-panel-head"><div><h3>Core Balances</h3><span>Current financial position by major account.</span></div></div><div class="core-balances"><?php foreach(['cash_on_hand','bank','jazzcash','easypaisa','payfast','accounts_receivable','subscription_revenue','advertisement_revenue'] as $key):$a=accounting_account_by_key($key);if(!$a)continue;$bal=accounting_account_balance((int)$a['id']);?><a href="?tab=ledger&account=<?=e($a['id'])?>"><span><b><?=e($a['name'])?></b><small><?=e($a['code'])?> · <?=e($a['account_type'])?></small></span><strong>Rs <?=e(number_format($bal,0))?></strong></a><?php endforeach;?></div></section></div>
<section class="card"><div class="acct-panel-head"><div><h3>Recent Journal Activity</h3><span>Automatic payment/invoice entries and manual journals.</span></div><a href="?tab=journal">Full journal</a></div><div class="acct-table-wrap"><table><tr><th>Date</th><th>Reference</th><th>Source</th><th>Description</th><th>Amount</th></tr><?php foreach(array_slice($journals,0,12) as $j):?><tr><td><?=e(date('d M Y',strtotime($j['journal_date'])))?></td><td><b><?=e($j['reference'])?></b></td><td><?=e($j['source_type'])?></td><td><?=e($j['description'])?></td><td>Rs <?=e(number_format((float)$j['amount'],2))?></td></tr><?php endforeach;?></table></div></section>

