<div class="ledger-layout"><aside class="card ledger-account-list"><h3>Accounts</h3><input class="input" id="accountSearch" placeholder="Search account..."><div id="accountList"><?php foreach($accounts as $a):?><a class="<?=$selectedAccount==$a['id']?'active':''?>" data-account-search="<?=e(strtolower($a['code'].' '.$a['name']))?>" href="?tab=ledger&account=<?=e($a['id'])?>"><span><b><?=e($a['code'])?></b><?=e($a['name'])?></span><strong>Rs <?=e(number_format(accounting_account_balance((int)$a['id']),0))?></strong></a><?php endforeach;?></div></aside><section class="card"><?php if($selected):?><div class="acct-panel-head"><div><h3><?=e($selected['code'].' · '.$selected['name'])?></h3><span><?=e(ucfirst($selected['account_type']))?> account · running balance</span></div><a href="?export=ledger&account=<?=e($selected['id'])?>">Export CSV</a></div><div class="acct-table-wrap"><table><tr><th>Date</th><th>Reference</th><th>Description</th><th>Business</th><th>Debit</th><th>Credit</th><th>Balance</th></tr><?php $running=0;foreach($ledger as $l):$running+=accounting_normal_balance((string)$selected['account_type'],(float)$l['debit'],(float)$l['credit']);?><tr><td><?=e(date('d M Y',strtotime($l['journal_date'])))?></td><td><?=e($l['reference'])?></td><td><?=e($l['description'])?><br><small><?=e($l['memo']?:'')?></small></td><td><?=e($l['business_name']?:'—')?></td><td><?=((float)$l['debit']>0)?'Rs '.e(number_format((float)$l['debit'],2)):'—'?></td><td><?=((float)$l['credit']>0)?'Rs '.e(number_format((float)$l['credit'],2)):'—'?></td><td><b>Rs <?=e(number_format($running,2))?></b></td></tr><?php endforeach;?></table></div><?php endif;?></section></div>
