<?php elseif($tab==='business'):?>
<div class="business-ledger-layout"><aside class="card"><h3>Business Statement</h3><form method="get"><input type="hidden" name="tab" value="business"><label>Business</label><select class="input" name="business_id" onchange="this.form.submit()"><option value="">Select business</option><?php foreach($businesses as $b):?><option value="<?=e($b['id'])?>" <?=$businessId==$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></form><?php if($businessInfo):$bi=subscription_invoices('',(int)$businessInfo['id'],100);$due=0;foreach($bi as $i)if(in_array($i['status'],['unpaid','partial','overdue'],true))$due+=(float)$i['total']-(float)$i['paid_amount'];?><div class="business-ledger-summary"><b><?=e($businessInfo['name'])?></b><span>Outstanding invoices</span><strong>Rs <?=e(number_format($due,0))?></strong></div><?php endif;?></aside><section class="card"><div class="acct-panel-head"><div><h3><?=e($businessInfo?$businessInfo['name'].' Ledger':'Select a Business')?></h3><span>All journal lines tagged to this business.</span></div></div><?php if($businessInfo):?><div class="acct-table-wrap"><table><tr><th>Date</th><th>Reference</th><th>Account</th><th>Description</th><th>Debit</th><th>Credit</th></tr><?php foreach($statement as $l):?><tr><td><?=e(date('d M Y',strtotime($l['journal_date'])))?></td><td><?=e($l['reference'])?></td><td><?=e($l['code'].' · '.$l['account_name'])?></td><td><?=e($l['description'])?><br><small><?=e($l['memo']?:'')?></small></td><td><?=((float)$l['debit']>0)?'Rs '.e(number_format((float)$l['debit'],2)):'—'?></td><td><?=((float)$l['credit']>0)?'Rs '.e(number_format((float)$l['credit'],2)):'—'?></td></tr><?php endforeach;?></table></div><?php else:?><div class="empty-state">Choose a business to view its account statement.</div><?php endif;?></section></div>

